    """PATCH {maintenance_mode, pause_scheduler} (sync, no task)."""
    return p.patch(f"/sites/{seg(site)}/configuration", {
        "maintenance_mode": 1 if on else 0,
        "pause_scheduler": int(on if pause_scheduler is None else pause_scheduler)})


